import{z as E,x as d,o as r,c as P,q as p,j as t,D as l,d as e,s,S as i,b as n}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"LP 松弛与舍入","description":"","frontmatter":{"title":"LP 松弛与舍入","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lp-rounding.md","filePath":"cs/lp-rounding.md","lastUpdated":1791063341000}'),B={name:"cs/lp-rounding.md"};function m(A,a,h,f,C,u){const o=d("Mermaid");return r(),P("div",null,[a[2]||(a[2]=p('<h1 id="lp-松弛与舍入" tabindex="-1">LP 松弛与舍入 <a class="header-anchor" href="#lp-松弛与舍入" aria-label="Permalink to &quot;LP 松弛与舍入&quot;">​</a></h1><div class="epigraph"><p>整数约束放松成 $[0,1]$；分数解舍入（随机或按阈值）给出近似，比由 LP/OPT 积分间隙控制。</p><footer>—— 据 Raghavan and Thompson, Randomized Rounding, 1987；CLRS 第 29、35 章；[LP 对偶](/cs/lp-duality) 整理</footer></div><p>上一课<a href="/cs/christofides">Christofides</a>走组合构造：近似比直接从度量性质读出。本课换一条路线：先写整数线性规划（ILP），把整数约束松弛成 \\([0,1]\\) 得到 LP，多项式可解。缺口在松弛之后——LP 给出的多是分数解，必须舍入成整数。舍入得当即得近似：顶点覆盖按阈值 \\(x_u\\ge 1/2\\) 则取，\\(2\\)-近似；集合覆盖随机舍入期望 \\(O(\\log n)\\)。后课<a href="/cs/knapsack-fptas">背包 FPTAS</a>是缩放价格的一路，不经 LP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>核心量是<strong>积分间隙</strong>：\\(\\sup\\mathrm{OPT}/\\mathrm{OPT}_{LP}\\)，即最坏情形下整数最优与分数最优之比，它钉住舍入的天花板：近似比不会优于间隙。随机舍入的做法：独立地以 \\(x_i\\) 为概率把变量取成 \\(1\\)，期望与分数解一致；约束被破坏的概率用 Chernoff 界住，超出再修补或调阈值。依赖舍入、迭代舍入只点名，本课不展开。</p><p>缺口是从分数回到整数、近似即可，不是精确搜索。</p><p><span class="marginnote">数字实例：三角形 \\(K_3\\) 的顶点覆盖，LP 松弛下三点各取 \\(1/2\\) 即可行（每条边两端之和 \\(=1\\)），费用 \\(1.5\\)；整数最优要选 2 个点，\\(\\mathrm{OPT}=2\\)。分数解凭空便宜了 \\(2/1.5=4/3\\) 倍——这就是「必须舍入」最直观的样子。</span></p><h3 id="松弛公式要选对" tabindex="-1">松弛公式要选对 <a class="header-anchor" href="#松弛公式要选对" aria-label="Permalink to &quot;松弛公式要选对&quot;">​</a></h3><p>同一问题能写出多个 ILP 公式，间隙各不相同：坏公式的 LP 松弛值远低于整数最优，舍入再好也救不回。顶点覆盖标准公式间隙是 \\(2\\)——每条边至少一端选，全取 \\(1/2\\) 即可行。要证明近似比，论证必须绑定在这个公式上；换公式等于换间隙。</p><p><span class="marginnote">Raghavan–Thompson 1987 把随机舍入做成通用方法，用 Chernoff 界顶住约束破坏。Goemans–Williamson 最大割 SDP 后课局部搜索旁点名。后课背包伪多项式 \\(\\to\\) FPTAS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程固定四步：建模 ILP \\(\\to\\) 松弛 \\(\\to\\) 解 LP \\(\\to\\) 舍入。证比常用对偶拟合：构造对偶可行解，把它的值与整数解按常数比例挂起，比值即近似比。拿到算法后要检查已知间隙实例，看比还能压到哪。</p>',12)),(r(),t(i,null,{default:l(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ILP%5B%22ILP%22%5D%20--%3E%20LP%5B%22%E6%9D%BE%E5%BC%9B%22%5D%0A%20%20LP%20--%3E%20RND%5B%22%E9%98%88%E5%80%BC%20%2F%20%E9%9A%8F%E6%9C%BA%E8%88%8D%E5%85%A5%22%5D%0A%20%20RND%20--%3E%20APX%5B%22%CF%81-%E8%BF%91%E4%BC%BC%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"无界间隙的公式则此路失败：分数最优能被任意压低，只能换公式或换路线。",-1)),a[4]||(a[4]=n("p",null,[n("span",{class:"marginnote"},"直觉类比：松弛像先允许「买半份」来估价——分数 LP 给出价格底线（下界），再花一点代价把半份拼回整份（舍入）。多花的这部分钱与「半份估价失真多少」（积分间隙）相乘，就是整套方法的近似比。")],-1)),a[5]||(a[5]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=n("p",null,"弱对偶保证 \\(\\mathrm{OPT}_{LP}\\) 是整数 OPT 的界：松弛放大可行域，最小化时分数值只会更低，舍入比因此可拆成舍入损失乘以间隙。随机舍入里约束不再硬性成立，改用概率：期望满足，破坏概率被集中不等式压小。与分支定界的分工：那里用界剪枝、追求精确，最坏指数时间；这里一次舍入收工，只保近似。与 KM 顶标对照：那是精确对偶，间隙 \\(0\\)，故无须舍入。",-1)),a[7]||(a[7]=n("p",null,[n("span",{class:"marginnote"},"常见误区：初学者容易把随机舍入理解成「四舍五入」。实际是以 \\(x_i\\) 为概率掷硬币取 \\(0/1\\)：期望上不亏 LP 值，同时允许个别约束以受控小概率被违反，违反概率由 Chernoff 界住、超出再修补——「近似」的让步就落在这两处。")],-1)),(r(),t(i,null,{default:l(()=>[s(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20VAL%5B%22LP%20%E6%9C%80%E4%BC%98%E5%80%BC%20OPT_LP%22%5D%20--%3E%20GAP%5B%22%E7%A7%AF%E5%88%86%E9%97%B4%E9%9A%99%20%CE%B3%EF%BC%9AOPT%20%E2%89%A4%20%CE%B3%20%C2%B7%20OPT_LP%22%5D%0A%20%20GAP%20--%3E%20RND%5B%22%E8%88%8D%E5%85%A5%EF%BC%9A%E6%9C%9F%E6%9C%9B%E5%80%BC%20%E2%89%A4%20%CE%B1%20%C2%B7%20OPT_LP%22%5D%0A%20%20RND%20--%3E%20TOT%5B%22%E8%BF%91%E4%BC%BC%E6%AF%94%20%E2%89%A4%20%CE%B1%20%C2%B7%20%CE%B3%22%5D%0A%20%20RND%20--%3E%20PROB%5B%22%E7%BA%A6%E6%9D%9F%E7%A0%B4%E5%9D%8F%E6%A6%82%E7%8E%87%20Chernoff%20%E4%B8%8A%E7%95%8C%22%5D%0A%20%20PROB%20--%3E%20REP%5B%22%E8%B6%85%E9%A2%84%E7%AE%97%E5%88%99%E4%BF%AE%E8%A1%A5%E6%88%96%E8%B0%83%E9%98%88%E5%80%BC%22%5D%0A%20%20REP%20--%3E%20TOT%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n("h2",{id:"边界",tabindex:"-1"},[e("边界 "),n("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[9]||(a[9]=n("p",null,"本课不写 SDP 与切平面，也不复现 Raghavan–Thompson 的完整 Chernoff 分析。后课默认：近似可走 LP 舍入，但比受积分间隙限制，公式选错则上限提前锁死。下一课背包 FPTAS。",-1)),a[10]||(a[10]=n("h2",{id:"小结",tabindex:"-1"},[e("小结 "),n("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[11]||(a[11]=n("ul",null,[n("li",null,"松弛 + 舍入；近似比不优于积分间隙。"),n("li",null,"随机舍入以期望保值，集中不等式管约束。"),n("li",null,"公式选择决定间隙，进而决定比的上限。"),n("li",null,"出处：Raghavan and Thompson, 1987；CLRS。")],-1))])}const D=E(B,[["render",m]]);export{T as __pageData,D as default};
